# Review package: 8e236f061645d5a8957c549c548950dfaad3d080..HEAD

## Commits
a8a3c4f fix: recognise typographic quotes in sentenceCount Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>

## Files changed
 src/textstats.js           |  4 ++--
 test/sentenceCount.test.js | 17 +++++++++++++++++
 2 files changed, 19 insertions(+), 2 deletions(-)

## Diff
diff --git a/src/textstats.js b/src/textstats.js
index 111b19b..a1dc110 100644
--- a/src/textstats.js
+++ b/src/textstats.js
@@ -29,28 +29,28 @@ function wordCount(text) {

 // Words whose trailing period does not end a sentence. Compared lower-case and
 // without any opening bracket or quote. "U.S.A." style initialisms are not
 // listed: they usually do end a sentence when they come last, and guessing
 // otherwise would trade one error for another.
 const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);

 // A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
 // only where whitespace or the end of the text follows. Requiring that keeps
 // decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
-const TERMINATOR_PATTERN = /([.!?]+)(["'"')\]]*)(?=\s|$)/g;
+const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;

 function endsWithAbbreviation(before) {
   const last = before.match(/(\S+)$/);
   if (last === null) {
     return false;
   }
-  const word = last[1].replace(/^["'"'(\[]+/, '').toLowerCase();
+  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
   return ABBREVIATIONS.has(word);
 }

 /**
  * Count the sentences in a piece of text.
  *
  * A sentence is a stretch of text containing at least one word and ending at a
  * terminator run, or at the end of the text. A lone period after a known
  * abbreviation does not end a sentence.
  *
diff --git a/test/sentenceCount.test.js b/test/sentenceCount.test.js
index c704b6e..d6dafb6 100644
--- a/test/sentenceCount.test.js
+++ b/test/sentenceCount.test.js
@@ -216,10 +216,27 @@ test('handles consecutive terminators correctly', () => {
   assert.equal(sentenceCount('What?! Really'), 2);
 });

 test('handles period in middle of sentence not followed by space', () => {
   assert.equal(sentenceCount('Version 1.0 released today.'), 1);
 });

 test('distinguishes abbreviation from non-abbreviation with same letters', () => {
   assert.equal(sentenceCount('Mister. Smith arrived. Mr. Jones left'), 3);
 });
+
+// Tests for typographic (curly) quotes - D2 requirement
+test('recognizes terminator followed by closing curly double quote then whitespace', () => {
+  assert.equal(sentenceCount('He said "Hi." Then left.'), 2);
+});
+
+test('recognizes terminator followed by closing curly single quote then whitespace', () => {
+  assert.equal(sentenceCount('She said ‘hello.’ He waved.'), 2);
+});
+
+test('ignores opening curly double quote before abbreviation in period check', () => {
+  assert.equal(sentenceCount('“Dr. Who” came. ok'), 2);
+});
+
+test('ignores opening curly single quote before abbreviation in period check', () => {
+  assert.equal(sentenceCount('‘Mr. Smith’ left. Then arrived.'), 2);
+});

